Lemma dg_ret : forall t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' s0' s1' s2' s3' t3' t4' t5' t6' (m : word -> option byte) j8 (res len kappa Ks : Z) (bs : list byte),
  stk rsegs m (SP0 - 48) (SP0 - 48) ->
  rw_cells rsegs m (SP0 - 48) [CB 8 j8; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra] ->
  munch DG_W m0 m -> wmono rsegs m0 m -> mem_inv rsegs m ->
  u8arr rsegs m buf bs -> length bs = 21%nat ->
  rw_cells rsegs m lenp [C4 (Z_to_bv 64 len)] -> (1 <= len <= 21)%Z ->
  rw_cells rsegs m kp [C4 (Z_to_bv 64 (Ks + kappa))] -> (-18 <= kappa <= 2)%Z ->
  a0' = Z_to_bv 64 res -> (res = 0 \/ res = 1)%Z ->
  (48 <= SP0 < 2 ^ 47)%Z ->
  evt rsegs (dg_post Ks) (MS (mkR ra (Z_to_bv 64 (SP0 - 48)) gp tp t0' t1' t2' s0' s1' a0' a1' a2' a3' a4' a5' a6' a7' s2' s3' s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6')
                              F (Z_to_bv 64 0x42fc0) fc None m (seg_rom rsegs)).
Proof.
  intros until bs. intros ST FR MU WM MI BU BL LE LR KC KR Ha0 Hres SPR. subst a0'.
  repeat zstep.
  try (replace (Z_to_bv 64 (SP0 - 48 + 48)) with sp
         by (unfold SP0; rewrite Z.sub_add; symmetry; apply Z_to_bv_bv_unsigned)).
  release_frame FR ST SP0.
  finish. all: first [eassumption | lia].
Qed.

