Lemma dg_rw2_loop : forall (n : nat) (D r one len : Z) t0' t1' t2' a0' a2' a3' a5' a7' s0' s1' s2' s3' t3' t5' t6' (m : word -> option byte) j8 (kappa Ks : Z) (bs : list byte),
  Z.to_nat (D - r) = n ->
  dg_mem m j8 s0' s1' s2' s3' len (Ks + kappa) bs -> (1 <= len <= 21)%Z -> (-18 <= kappa <= 2)%Z ->
  (0 <= r)%Z -> (1 <= one)%Z -> (r + one <= D)%Z -> (D < 2 ^ 64)%Z ->
  evt rsegs (dg_post Ks) (MS (mkR ra (Z_to_bv 64 (SP0 - 48)) gp tp t0' t1' t2' s0' s1' a0' (Z_to_bv 64 one) a2' a3' (Z_to_bv 64 r) a5' (Z_to_bv 64 (buf + len)) a7'
                                  s2' s3' s4 s5 s6 s7 s8 s9 s10 s11 t3' (Z_to_bv 64 (D - r - one)) t5' t6')
                              F (Z_to_bv 64 0x42efc) fc None m (seg_rom rsegs)).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D r one len t0' t1' t2' a0' a2' a3' a5' a7' s0' s1' s2' s3' t3' t5' t6' m j8 kappa Ks bs Hn HM LR KR Hr Ho Hro HD.
  pose proof HM as HM0. dg_mem_intro HM.
  assert (BODY : forall t0x, evt rsegs (dg_post Ks)
     (MS (mkR ra (Z_to_bv 64 (SP0 - 48)) gp tp t0x t1' t2' s0' s1' a0' (Z_to_bv 64 one) (Z_to_bv 64 (r + one)) a3' (Z_to_bv 64 r) a5' (Z_to_bv 64 (buf + len)) a7'
              s2' s3' s4 s5 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 (D - r - one)) (Z_to_bv 64 (D - r - one)) t5' t6')
         F (Z_to_bv 64 0x42f10) fc None m (seg_rom rsegs))).
  { intros t0x.
    assert (Hi : (Z.to_nat (len - 1) < length bs)%nat) by lia.
    destruct (nth_error bs (Z.to_nat (len - 1))) as [b|] eqn:Hb; [|apply nth_error_None in Hb; lia].
    pose proof (u8arr_read rsegs m buf bs (len - 1) b (Z_to_bv 64 (buf + len + -1)) BU Hb ltac:(lia) ltac:(unfold wa; f_equal; lia)) as RD.
    zstep. zstep.
    pose proof (u8arr_store_ok rsegs m buf bs (len - 1) (Z_to_bv 64 (buf + len + -1)) BU ltac:(lia) ltac:(unfold wa; f_equal; lia)) as SOK.
    zstep.
    set (b' := Z_to_bv 8 (bv_unsigned b + -1)).
    replace (write_to_mem m (Z_to_bv 64 (buf + len + -1)) (le1 (Z_to_bv 64 (bv_unsigned b + -1)))) with (write_to_mem m (wa (buf + (len - 1))) [b'])
      by (f_equal; [unfold wa; f_equal; lia | symmetry; apply le1_lit]).
    pose proof (u8arr_write rsegs m buf bs (len - 1) b' BU ltac:(lia)) as BU'.
    clear BU RD. store_done.
    assert (HM1 : dg_mem m1 j8 s0' s1' s2' s3' len (Ks + kappa) (upd bs (Z.to_nat (len - 1)) b')).
    { unfold dg_mem. split; [exact ST|]. split; [exact FR|]. split; [exact MU|]. split; [exact WM|]. split; [exact MI|]. split; [exact BU'|].
      split; [rewrite upd_length; exact BL|]. split; [exact LE | exact KC]. }
    zstep. zstep. if_cases K2.
    + eapply dg_weed2; [exact HM1 | exact LR | exact KR | lia].
    + do 3 zstep. zstep. if_cases K3; zify_cond K3.
      * replace (Z_to_bv 64 (D - r - one - one)) with (Z_to_bv 64 (D - (r + one) - one)) by (f_equal; lia).
        eapply (IH (Z.to_nat (D - (r + one)))); [lia | reflexivity | exact HM1 | exact LR | exact KR | lia | lia | lia | lia].
      * zstep. eapply dg_weed2; [exact HM1 | exact LR | exact KR | lia].
  }
  do 3 zstep. if_cases K1.
  - apply BODY.
  - do 2 zstep. if_cases K4.
    + do 2 zstep. eapply dg_weed2; [exact HM0 | exact LR | exact KR | lia].
    + apply BODY.
Qed.

Lemma dg_rw1_loop : forall (n : nat) (D r tk len : Z) t0' t1' t2' a1' a2' a3' a5' a7' s0' s1' s2' s3' t3' t4' t6' (m : word -> option byte) j8 (kappa Ks : Z) (bs : list byte),
  Z.to_nat (D - r) = n ->
  dg_mem m j8 s0' s1' s2' s3' len (Ks + kappa) bs -> (1 <= len <= 21)%Z -> (-18 <= kappa <= 2)%Z ->
  (0 <= r)%Z -> (1 <= tk)%Z -> (r + tk <= D)%Z -> (D < 2 ^ 64)%Z ->
  evt rsegs (dg_post Ks) (MS (mkR ra (Z_to_bv 64 (SP0 - 48)) gp tp t0' t1' t2' s0' s1' (Z_to_bv 64 D) a1' a2' a3' (Z_to_bv 64 tk) a5' (Z_to_bv 64 (buf + len)) a7'
                                  s2' s3' s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' (Z_to_bv 64 r) t6')
                              F (Z_to_bv 64 0x42e1c) fc None m (seg_rom rsegs)).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros D r tk len t0' t1' t2' a1' a2' a3' a5' a7' s0' s1' s2' s3' t3' t4' t6' m j8 kappa Ks bs Hn HM LR KR Hr Ho Hro HD.
  pose proof HM as HM0. dg_mem_intro HM.
  assert (BODY : forall t0x a7x, evt rsegs (dg_post Ks)
     (MS (mkR ra (Z_to_bv 64 (SP0 - 48)) gp tp t0x t1' t2' s0' s1' (Z_to_bv 64 D) a1' a2' a3' (Z_to_bv 64 tk) (Z_to_bv 64 (r + tk)) (Z_to_bv 64 (buf + len)) a7x
              s2' s3' s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' (Z_to_bv 64 r) t6')
         F (Z_to_bv 64 0x42e30) fc None m (seg_rom rsegs))).
  { intros t0x a7x.
    assert (Hi : (Z.to_nat (len - 1) < length bs)%nat) by lia.
    destruct (nth_error bs (Z.to_nat (len - 1))) as [b|] eqn:Hb; [|apply nth_error_None in Hb; lia].
    pose proof (u8arr_read rsegs m buf bs (len - 1) b (Z_to_bv 64 (buf + len + -1)) BU Hb ltac:(lia) ltac:(unfold wa; f_equal; lia)) as RD.
    zstep. zstep. zstep.
    pose proof (u8arr_store_ok rsegs m buf bs (len - 1) (Z_to_bv 64 (buf + len + -1)) BU ltac:(lia) ltac:(unfold wa; f_equal; lia)) as SOK.
    zstep.
    set (b' := Z_to_bv 8 (bv_unsigned b + -1)).
    replace (write_to_mem m (Z_to_bv 64 (buf + len + -1)) (le1 (Z_to_bv 64 (bv_unsigned b + -1)))) with (write_to_mem m (wa (buf + (len - 1))) [b'])
      by (f_equal; [unfold wa; f_equal; lia | symmetry; apply le1_lit]).
    pose proof (u8arr_write rsegs m buf bs (len - 1) b' BU ltac:(lia)) as BU'.
    clear BU RD. store_done.
    assert (HM1 : dg_mem m1 j8 s0' s1' s2' s3' len (Ks + kappa) (upd bs (Z.to_nat (len - 1)) b')).
    { unfold dg_mem. split; [exact ST|]. split; [exact FR|]. split; [exact MU|]. split; [exact WM|]. split; [exact MI|]. split; [exact BU'|].
      split; [rewrite upd_length; exact BL|]. split; [exact LE | exact KC]. }
    zstep. zstep. if_cases K2.
    + eapply dg_weed1; [exact HM1 | exact LR | exact KR | lia].
    + zstep. zstep. if_cases K3; zify_cond K3.
      * eapply (IH (Z.to_nat (D - (r + tk)))); [lia | reflexivity | exact HM1 | exact LR | exact KR | lia | lia | lia | lia].
      * zstep. eapply dg_weed1; [exact HM1 | exact LR | exact KR | lia].
  }
  zstep. zstep. if_cases K1.
  - apply BODY.
  - do 3 zstep. if_cases K4.
    + do 2 zstep. eapply dg_weed1; [exact HM0 | exact LR | exact KR | lia].
    + apply BODY.
Qed.

Lemma dg_l2exit : forall (Dold r one len kappa Ks : Z) t1' t2' a2' a3' a5' s0' s1' s2' s3' t5' t6' (m : word -> option byte) j8 (bs : list byte),
  dg_mem m j8 s0' s1' s2' s3' len Ks bs -> (1 <= len <= 21)%Z -> (-18 <= kappa <= -1)%Z -> (- 2 ^ 31 + 18 <= Ks <= 2 ^ 31 - 3)%Z ->
  (0 <= r < 10 * Dold)%Z -> (1 <= one <= 2 ^ 59)%Z -> (10 * Dold < 2 ^ 63)%Z ->
  evt rsegs (dg_post Ks) (MS (mkR ra (Z_to_bv 64 (SP0 - 48)) gp tp (Z_to_bv 64 kp) t1' t2' s0' s1' (Z_to_bv 64 (10 * Dold)) (Z_to_bv 64 one) a2' a3' (Z_to_bv 64 r) a5'
                                  (Z_to_bv 64 buf) (Z_to_bv 64 lenp) s2' s3' s4 s5 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 Dold) (Z_to_bv 64 kappa) t5' t6')
                              F (Z_to_bv 64 0x42ea8) fc None m (seg_rom rsegs)).
Proof.
  intros until bs. intros HM LR KR KsR Hr Ho HD.
  pose proof HM as HM0. dg_mem_intro HM.
  zstep. rewrite sx32_small by lia.
  zstep. zstep. zstep.
  assert (HM1 : dg_mem m1 j8 s0' s1' s2' s3' len (Ks + kappa) bs).
  { unfold dg_mem. split; [exact ST|]. split; [exact FR|]. split; [exact MU|]. split; [exact WM|]. split; [exact MI|]. split; [exact BU|].
    split; [exact BL|]. split; [exact LE | exact KC]. }
  do 4 zstep. zstep. if_cases K1.
  - zstep. eapply dg_weed2; [exact HM1 | exact LR | lia | lia].
  - zstep. if_cases K2; zify_cond K2.
    + zstep. eapply dg_weed2; [exact HM1 | exact LR | lia | lia].
    + zstep. rewrite sx32_small by lia. do 10 zstep.
      replace (Z_to_bv 64 (Dold * 10 - (one + r))) with (Z_to_bv 64 (10 * Dold - r - one)) by (f_equal; lia).
      eapply (dg_rw2_loop (Z.to_nat (10 * Dold - r)) (10 * Dold) r one len); [reflexivity | exact HM1 | exact LR | lia | lia | lia | lia | lia].
Qed.

Lemma dg_loop2 : forall (n : nat) (i p2 D s len Ks : Z) t3' a2' a3' s0' s1' s2' s3' (m : word -> option byte) j8 (bs : list byte),
  Z.to_nat (17 - i) = n ->
  dg_mem m j8 s0' s1' s2' s3' len Ks bs -> (1 <= len <= 3 + i)%Z -> (0 <= i <= 17)%Z -> (- 2 ^ 31 + 18 <= Ks <= 2 ^ 31 - 3)%Z ->
  (56 <= s <= 59)%Z -> (D <= p2 < 2 ^ s)%Z -> (2 * 10 ^ i <= D)%Z ->
  evt rsegs (dg_post Ks) (MS (mkR ra (Z_to_bv 64 (SP0 - 48)) gp tp (Z_to_bv 64 kp) (Z_to_bv 64 (2 ^ 32 - 1)) (Z_to_bv 64 (2 ^ s - 1)) s0' s1' (Z_to_bv 64 D) (Z_to_bv 64 (2 ^ s)) a2' a3'
                                  (Z_to_bv 64 p2) (Z_to_bv 64 s) (Z_to_bv 64 buf) (Z_to_bv 64 lenp) s2' s3' s4 s5 s6 s7 s8 s9 s10 s11 t3' (Z_to_bv 64 (- i)) (Z_to_bv 64 10) (Z_to_bv 64 (10 ^ i)))
                              F (Z_to_bv 64 0x42e60) fc None m (seg_rom rsegs)).
Proof.
  induction n as [n IH] using lt_wf_ind.
  intros i p2 D s len Ks t3' a2' a3' s0' s1' s2' s3' m j8 bs Hn HM LR IR KsR Hs HP HD.
  pose proof HM as HM0. dg_mem_intro HM.
  assert (H2s : (2 ^ 56 <= 2 ^ s <= 2 ^ 59)%Z) by (split; apply Z.pow_le_mono_r; lia).
  assert (H10 : (1 <= 10 ^ i < 2 ^ 58)%Z).
  { split; [pose proof (Z.pow_pos_nonneg 10 i ltac:(lia) ltac:(lia)); lia|].
    apply Z.le_lt_trans with (10 ^ 17)%Z; [apply Z.pow_le_mono_r; lia | vm_compute; reflexivity]. }
  assert (HLm : (Z.land (p2 * 10) (2 ^ s - 1) < 2 ^ s)%Z)
    by (replace (2 ^ s - 1)%Z with (Z.ones s) by (rewrite Z.ones_equiv; lia); rewrite Z.land_ones by lia; apply Z.mod_pos_bound; lia).
  assert (HL0 : (0 <= Z.land (p2 * 10) (2 ^ s - 1))%Z) by (apply Z.land_nonneg; lia).
  zstep. zstep. rewrite sx32_small by lia. do 4 zstep. zstep.
  if_cases K1; [ | zstep; if_cases K2; zify_cond K2; [lia | ] ].
  all: zstep; zstep; zstep; zstep;
    lazymatch type of BU with u8arr _ ?mc _ _ =>
      pose proof (u8arr_store_ok rsegs mc buf bs len (Z_to_bv 64 (buf + len)) BU ltac:(lia) ltac:(unfold wa; f_equal; lia)) as SOK end;
